<?php
namespace BeeUpdater;
final class UpdateEngine {
    public function __construct(private readonly string $base) {}
    public function apply(string $zipPath,?string $password=null): array {
        $kernel=new Kernel($this->base);$before=Common::installed();$beforeVersion=(string)($before['version']??'0.0.0');$verified=$kernel->verify($zipPath,$beforeVersion);$release=$verified['release'];$manifest=$verified['manifest'];$targetVersion=(string)$release['version'];$targetSchema=(int)$release['schema_version'];
        $work=$this->base.'/storage/app/private/updates/work/'.preg_replace('/[^A-Za-z0-9._-]/','_', (string)$release['release_id']).'-'.bin2hex(random_bytes(3));if(!is_dir($work)&&!mkdir($work,0700,true))throw new \RuntimeException('Cannot create work directory');$archive=$work.'/package.zip';if(!copy($zipPath,$archive))throw new \RuntimeException('Cannot stage package');$kernel->safeExtract($archive,$work.'/extracted');
        $backupMgr=new BackupManager($this->base);$rollbackFiles=[];$createdFiles=[];foreach($manifest['files']??[] as $file){$path=(string)$file['path'];if(str_starts_with($path,'payload/')){$dest=substr($path,8);$rollbackFiles[]=$dest;if(!is_file($this->base.'/'.$dest))$createdFiles[]=$dest;}}
        $backup=null;$pdo=Common::pdo();$pdo->prepare("INSERT INTO update_runs (release_id,from_version,to_version,status,started_at) VALUES (?,?,?,?,NOW())")->execute([$release['release_id'],$beforeVersion,$targetVersion,'STARTED']);$runId=(int)$pdo->lastInsertId();
        try{
            $backup=$backupMgr->create((string)$release['release_id'],$rollbackFiles);$pdo->prepare("UPDATE update_runs SET backup_path=? WHERE id=?")->execute([$backup['directory'],$runId]);
            $payload=$work.'/extracted/payload';if(is_dir($payload))$this->copyTree($payload,$this->base);
            foreach($manifest['migrations']??[] as $migration){$path=$work.'/extracted/'.(string)$migration['path'];$type=(string)($migration['type']??'sql');if($type==='sql')$pdo->exec((string)file_get_contents($path));elseif($type==='php'){$call=require $path;if(is_callable($call))$call($pdo,$this->base);}elseif($type==='artisan'){CommandRunner::run('php artisan '.(string)$migration['command'],$this->base,180);}}
            $afterMigrate=Common::pdo();$actualSchema=(int)($afterMigrate->query("SELECT schema_version FROM platform_versions WHERE id=1")->fetchColumn()?:0);if($actualSchema!==$targetSchema)throw new \RuntimeException('Schema version did not reach release target');
            foreach($manifest['postflight']??[] as $check){$this->postflight((array)$check);}
            $installed=['version'=>$targetVersion,'schema_version'=>$targetSchema,'release_id'=>$release['release_id'],'installed_at'=>gmdate('c')];file_put_contents($this->base.'/storage/app/private/installed-release.json',json_encode($installed,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);$pdo->prepare("UPDATE update_runs SET status='ACTIVE',finished_at=NOW() WHERE id=?")->execute([$runId]);
            return ['status'=>'ACTIVE','release'=>$installed,'backup'=>$backup['directory'],'verification'=>$verified];
        }catch(\Throwable $e){if($backup!==null){try{$backupMgr->restore($backup);foreach($createdFiles as $relative){$full=$this->base.'/'.$relative;if(is_file($full)||is_link($full))@unlink($full);} }catch(\Throwable $restoreError){try{$pdo=Common::pdo();$pdo->prepare("UPDATE update_runs SET status='ROLLBACK_FAILED',error_message=?,finished_at=NOW() WHERE id=?")->execute([$e->getMessage().' | restore: '.$restoreError->getMessage(),$runId]);}catch(\Throwable){}throw new \RuntimeException('Update failed and rollback also failed: '.$restoreError->getMessage(),0,$e);}}try{$pdo=Common::pdo();$pdo->prepare("UPDATE update_runs SET status='ROLLED_BACK',error_message=?,finished_at=NOW() WHERE id=?")->execute([$e->getMessage(),$runId]);}catch(\Throwable){}throw $e;}
    }
    private function copyTree(string $source,string $dest): void {$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($source,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::SELF_FIRST);foreach($it as $entry){$relative=substr($entry->getPathname(),strlen($source)+1);$target=$dest.'/'.$relative;if($entry->isDir()){if(!is_dir($target)&&!mkdir($target,0755,true))throw new \RuntimeException('Cannot create '.$target);}else{$dir=dirname($target);if(!is_dir($dir))mkdir($dir,0755,true);if(!copy($entry->getPathname(),$target))throw new \RuntimeException('Cannot update '.$relative);}}}
    private function postflight(array $check): void {$type=$check['type']??'';if($type==='file_exists'&&!is_file($this->base.'/'.(string)$check['path']))throw new \RuntimeException('Postflight file missing');if($type==='artisan')CommandRunner::run('php artisan '.(string)$check['command'],$this->base,180);if($type==='sql'){$actual=Common::pdo()->query((string)$check['query'])->fetchColumn();if((string)$actual!==(string)$check['equals'])throw new \RuntimeException('Postflight SQL check failed');}}
}
